SELECT CASE WHEN c.credit_limit >= 14400 THEN 'high' WHEN c.credit_limit >= 4600 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, ROUND(AVG(o.amount), 2) AS avg_amount FROM orders o INNER JOIN stores s ON o.store_id = s.id INNER JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 14400 THEN 'high' WHEN c.credit_limit >= 4600 THEN 'mid' ELSE 'low' END ORDER BY credit_limit_bucket DESC, avg_amount DESC
